//! The contract ledger text, byte for byte as scripts/generate_parity_ledger.py `render_ledger`
//! renders it.

use std::collections::{BTreeMap, BTreeSet};

use anyhow::{Result, bail};

use super::statuses::{ParityStatus, is_dropped};
use super::waivers::Waiver;

const UNCLASSIFIED: &str = "**unclassified**";

/// The document lines before the count line, from the title through the blank line.
const HEAD: &[&str] = &[
    "# Parity ledger",
    "",
    "Generated by `uv run python -m scripts.generate_parity_ledger`; do not edit this document.",
    "Edit your group file in `docs/contracts/parity-ledger-status.d/`, then regenerate.",
    "All JSON shards merge in filename order; duplicate surface keys are errors.",
    "Each entry is a status string or an object: `{\"status\": \"proxied\", \"note\": \"Rust work\"}`.",
    "Objects require exactly `status` and `note`, both strings. Statuses are `proxied`,",
    "`delegated`, or `dropped by decision #N` (a positive task number). Notes cite evidence",
    "or blocking Rust work; string entries have empty notes. Pipes and line breaks in notes",
    "are escaped for the table. Malformed entries are errors.",
    "",
    "Exit rule: every row must be `delegated` or `dropped by decision <ref>` with a recorded",
    "decision. `proxied` and **unclassified** rows block #21573, the S3.2 naming switch",
    "with Python removed. Deletion child #21574 owns the mechanical deletion, gated by",
    "this exit check before the switch.",
    "The native terminal default flip has its own evidence row referencing #21357",
    "Plan native runtime completion. A closed planning task alone does not prove the flip.",
    "",
    "Sources: registered FastAPI/ASGI routes (including MCP and WS transports), inbound",
    "WebSocket dispatch messages, built-in MCP registries, daemon HTTP /mcp tools,",
    "the agent-facing stdio MCP bridge (`gobby mcp-server`), and",
    "registered Click verbs (groups and aliases included). Registration uses inert services;",
    "no daemon, database connection or handler runs. Deployment-specific external MCP",
    "servers and UI asset/dev-server mounts are outside this backend inventory.",
    "`HTTP *` denotes an ASGI route with no method filter in the parent route table.",
    "Dropped rows remain as decision evidence after removal; other mapping keys must",
    "identify currently registered surfaces. Unmapped surfaces are visibly unclassified.",
    "Parity waivers in `docs/contracts/parity-waivers.json` cite a changed behaviour inside a",
    "row; the row status is unchanged and the note reads `Waived`. `native-extension` rows are",
    "additive surfaces with no Python counterpart; their readiness comes from native tests alone.",
    "",
];

/// The rendered document, and how many of its rows block the exit rule.
pub struct Rendered {
    pub text: String,
    /// Rows that are neither `delegated` nor `dropped by decision #N`.
    pub blocking: usize,
}

/// Render the ledger from the frozen row keys, the merged statuses and the waivers.
pub fn render(
    surfaces: &BTreeSet<String>,
    statuses: &BTreeMap<String, ParityStatus>,
    waivers: &BTreeMap<String, Waiver>,
) -> Result<Rendered> {
    // Waivers are visited in id order, so each surface's list is already sorted by id.
    let mut cited: BTreeMap<&str, Vec<&Waiver>> = BTreeMap::new();
    for waiver in waivers.values() {
        cited
            .entry(waiver.surface.as_str())
            .or_default()
            .push(waiver);
    }
    // Statuses for surfaces the frozen rows lack are kept only as dropped-by-decision evidence.
    let stale: Vec<&str> = statuses
        .keys()
        .map(String::as_str)
        .filter(|surface| !surfaces.contains(*surface))
        .collect();
    let invalid: BTreeSet<&str> = stale
        .iter()
        .copied()
        .filter(|surface| {
            !statuses
                .get(*surface)
                .is_some_and(|entry| entry.status.starts_with("dropped by decision "))
        })
        .collect();
    if !invalid.is_empty() {
        let names: Vec<&str> = invalid.into_iter().collect();
        bail!("Mapping references absent surfaces: {}", names.join(", "));
    }
    let rows: BTreeSet<&str> = surfaces
        .iter()
        .map(String::as_str)
        .chain(stale.iter().copied())
        .collect();
    let unclassified = rows
        .iter()
        .filter(|&&surface| !statuses.contains_key(surface))
        .count();
    let blocking = rows
        .iter()
        .filter(|&&surface| {
            statuses
                .get(surface)
                .is_none_or(|entry| !(entry.status == "delegated" || is_dropped(&entry.status)))
        })
        .count();

    let mut lines: Vec<String> = HEAD.iter().map(|line| (*line).to_owned()).collect();
    lines.push(format!(
        "Public surfaces and evidence gates: {}. Unclassified: {unclassified}.",
        rows.len()
    ));
    lines.push(String::new());
    lines.push("| Public surface | Rust status | Notes |".to_owned());
    lines.push("| --- | --- | --- |".to_owned());
    for surface in &rows {
        let escaped = surface.replace('|', "\\|");
        let (status, mut parts) = match statuses.get(*surface) {
            Some(entry) if entry.note.is_empty() => (entry.status.clone(), Vec::new()),
            Some(entry) => (entry.status.clone(), vec![entry.note.clone()]),
            None => (UNCLASSIFIED.to_owned(), Vec::new()),
        };
        for waiver in cited.get(surface).into_iter().flatten() {
            parts.push(waiver_note(waiver));
        }
        let note = escape_note(&parts.join("\n"));
        lines.push(format!("| `{escaped}` | {status} | {note} |"));
    }
    Ok(Rendered {
        text: format!("{}\n", lines.join("\n")),
        blocking,
    })
}

/// The note a waiver adds to its row.
fn waiver_note(waiver: &Waiver) -> String {
    format!(
        "Waived `{}` ({}): {} Replacement: {}",
        waiver.id, waiver.decision, waiver.behaviour, waiver.replacement
    )
}

/// Escape a note for one table cell: backslashes, pipes, then line breaks become `<br>`.
fn escape_note(joined: &str) -> String {
    joined
        .replace('\\', "\\\\")
        .replace('|', "\\|")
        .replace("\r\n", "\n")
        .replace('\r', "\n")
        .replace('\n', "<br>")
}
